package employee.management.system;import net.proteanit.sql.DbUtils;import javax.swing.*;import java.awt.*;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;import java.sql.ResultSet;public class View_Employee extends JFrame implements ActionListener {    JTable table;    Choice choiceEMP;    JButton searchbtn, print, update, back;    View_Employee() {        setTitle("View Employee Details");        setSize(950, 650);        setLocation(300, 100);        setLayout(null);        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);        getContentPane().setBackground(new Color(20, 20, 20));        JLabel heading = new JLabel("Employee Records", SwingConstants.CENTER);        heading.setBounds(0, 20, 950, 40);        heading.setFont(new Font("Segoe UI", Font.BOLD, 28));        heading.setForeground(Color.WHITE);        add(heading);        JLabel search = new JLabel("Search by Employee ID:");        search.setBounds(50, 80, 200, 25);        search.setFont(new Font("Segoe UI", Font.PLAIN, 16));        search.setForeground(Color.WHITE);        add(search);        choiceEMP = new Choice();        choiceEMP.setBounds(250, 80, 180, 25);        add(choiceEMP);        try {            conn c = new conn();            ResultSet resultSet = c.s.executeQuery("SELECT empId FROM employee");            while (resultSet.next()) {                choiceEMP.add(resultSet.getString("empId"));            }        } catch (Exception e) {            e.printStackTrace();        }        searchbtn = createMetallicButton("Search");        searchbtn.setBounds(450, 80, 100, 30);        searchbtn.addActionListener(this);        add(searchbtn);        print = createMetallicButton("Print");        print.setBounds(560, 80, 100, 30);        print.addActionListener(this);        add(print);        update = createMetallicButton("Update");        update.setBounds(670, 80, 100, 30);        update.addActionListener(this);        add(update);        back = createMetallicButton("Back");        back.setBounds(780, 80, 100, 30);        back.addActionListener(this);        add(back);        table = new JTable();        table.setBackground(new Color(40, 40, 40));        table.setForeground(Color.WHITE);        table.setFont(new Font("Segoe UI", Font.PLAIN, 14));        table.setRowHeight(25);        table.getTableHeader().setFont(new Font("Segoe UI", Font.BOLD, 14));        table.getTableHeader().setBackground(new Color(60, 60, 60));        table.getTableHeader().setForeground(Color.WHITE);        try {            conn c = new conn();            ResultSet resultSet = c.s.executeQuery("SELECT * FROM employee");            table.setModel(DbUtils.resultSetToTableModel(resultSet));        } catch (Exception e) {            e.printStackTrace();        }        JScrollPane scroll = new JScrollPane(table);        scroll.setBounds(25, 130, 900, 460);        scroll.getViewport().setBackground(new Color(25, 25, 25));        add(scroll);        setVisible(true);    }    private JButton createMetallicButton(String text) {        JButton button = new JButton(text);        button.setFont(new Font("Segoe UI", Font.BOLD, 14));        button.setForeground(Color.WHITE);        button.setBackground(new Color(50, 50, 50));        button.setUI(new MetallicButtonUI());        return button;    }    @Override    public void actionPerformed(ActionEvent e) {        if (e.getSource() == searchbtn) {            String query = "SELECT * FROM employee WHERE empId = '" + choiceEMP.getSelectedItem() + "'";            try {                conn c = new conn();                ResultSet resultSet = c.s.executeQuery(query);                table.setModel(DbUtils.resultSetToTableModel(resultSet));            } catch (Exception ex) {                ex.printStackTrace();            }        } else if (e.getSource() == print) {            try {                table.print();            } catch (Exception ex) {                ex.printStackTrace();            }        } else if (e.getSource() == update) {            setVisible(false);            new UpdateEmployee(choiceEMP.getSelectedItem());        } else if (e.getSource() == back) {            setVisible(false);            new Main_class();        }    }    public static void main(String[] args) {        new View_Employee();    }}